"""Submission checks for task jlens-steer-assoc-017 (TASK.md). Run: .venv/bin/python -m pytest eval/test_submission.py -q"""

import json
import sys
from pathlib import Path

import pytest
import torch

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "tools"))
import metric  # noqa: E402

SUB = ROOT / "submission" / "submission.json"


@pytest.fixture(scope="module")
def sub() -> dict:
    assert SUB.exists(), "no submission: run eval/submit.py"
    return json.loads(SUB.read_text())


@pytest.fixture(scope="module")
def rerun(sub) -> dict:
    vecs = {int(L): v for L, v in torch.load(ROOT / sub["vectors"], weights_only=False).items()}
    return metric.run_metric(vecs, sub["positions"], sub["scale"])


def test_fields(sub):
    for k in ("task_id", "vectors", "positions", "scale", "method", "contribution", "fit_pass_at_10"):
        assert k in sub, f"missing {k}"
    assert sub["positions"] in ("prefix", "read", "context")
    assert sub["method"].strip()


def test_contribution(sub):
    n = len((ROOT / sub["contribution"]).read_text().split())
    assert 40 <= n <= 300, f"contribution has {n} words"


def test_score_reproduces(sub, rerun):
    assert abs(rerun["pass_at_10"] - sub["fit_pass_at_10"]) <= 0.01, "re-run does not reproduce the reported score"

"""Client for the steering metric server (the model runs on the GPU box; this machine only sends requests).

The server holds Qwen3.5-4B and its J-lens, and scores a steering intervention on the association dev split:
strict pass@10 and the mean log10 best target rank, read with the plain J-lens at the layers after the band.

    python tools/metric.py info
    python tools/metric.py run out/steer/v.pt [--positions prefix|read|context] [--scale 1.0]
    python tools/metric.py capture spec.json --out out/steer/means.pt

``v.pt`` is ``{layer: tensor[d_model]}``: added to the residual stream at the output of each listed block. A capture
spec is JSON: ``{"layers": [...], "prompts": [{"user": ..., "assistant": ...}], "positions": "last" | "user" |
"assistant" | "all"}``, or ``{"layers": [...], "bench_items": [ids], "family": ..., "split": ...}`` to read a bench
bank's own read cells. The server address is ``JLM_METRIC_URL`` (default ``http://localhost:8765``).
"""

import argparse
import base64
import json
import os
import sys
import urllib.request

import torch

URL = os.environ.get("JLM_METRIC_URL", "http://localhost:8765")


def _call(path: str, body: dict | None = None, timeout: float = 900) -> dict:
    data = None if body is None else json.dumps(body).encode()
    req = urllib.request.Request(URL + path, data=data, headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read())
    except urllib.error.HTTPError as e:
        raise RuntimeError(json.loads(e.read()).get("error", str(e))) from None


def _enc(t: torch.Tensor) -> dict:
    return {"b64": base64.b64encode(t.detach().float().cpu().contiguous().numpy().tobytes()).decode()}


def _dec(x: dict) -> torch.Tensor:
    t = torch.frombuffer(bytearray(base64.b64decode(x["b64"])), dtype=torch.float32).clone()
    return t.reshape(x["shape"])


def info() -> dict:
    return _call("/info")


def run_metric(vectors: dict[int, torch.Tensor], positions: str = "prefix", scale: float = 1.0) -> dict:
    """Score ``vectors`` (layer -> [d_model]) added at ``positions`` of every item; returns the fit numbers."""
    return _call("/run_metric", {"vectors": {str(L): _enc(v) for L, v in vectors.items()}, "positions": positions,
                                 "scale": scale})


def capture(spec: dict) -> dict:
    """Residual means for a capture spec: ``{"n_prompts", "layers", "mean": {L: [d]}, "per_prompt"?: {L: [n, d]}}``."""
    out = _call("/capture", spec)
    for k in ("mean", "per_prompt"):
        if k in out:
            out[k] = {int(L): _dec(v) for L, v in out[k].items()}
    return out


def main() -> None:
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("info")
    r = sub.add_parser("run")
    r.add_argument("vectors")
    r.add_argument("--positions", default="prefix", choices=("prefix", "read", "context"))
    r.add_argument("--scale", type=float, default=1.0)
    c = sub.add_parser("capture")
    c.add_argument("spec")
    c.add_argument("--out", required=True)
    a = ap.parse_args()
    if a.cmd == "info":
        print(json.dumps(info(), indent=1))
    elif a.cmd == "run":
        vecs = {int(L): v for L, v in torch.load(a.vectors, weights_only=False).items()}
        print(json.dumps(run_metric(vecs, a.positions, a.scale), indent=1, ensure_ascii=False))
    else:
        with open(a.spec) as f:
            out = capture(json.load(f))
        torch.save(out, a.out)
        print(f"{out['n_prompts']} prompts, layers {out['layers']} -> {a.out}", file=sys.stderr)


if __name__ == "__main__":
    main()

"""The free scorers: jle's strict match (single-token families) and target rank.

Strict: a cell hits when one of its top-10 display tokens equals an accepted form after one
leading space is stripped and the string casefolded; whole tokens only. An item passes when any
of its cells hits at any layer. Scored items are jle's confirmatory subset (x89): reachable (a
target is a single word; it may still take several tokens, and then the item cannot pass), not
leaky (no prompt token spells a target; not applied to directed_modulation, whose prompt names
the concept by design), and for basic_readout not the implicit items. These are OUR numbers, a lower bound on the bench judge,
never "WorkspaceBench scores".

``extra`` (every scorer below): more accepted forms per target set, keyed by ``form_key`` of the item's own forms
(``jlm.forms``: inflections, the "strict + forms" score). Without it, the bench's strict rule.
"""

from collections import defaultdict
from collections.abc import Iterable, Mapping
from typing import Any

import numpy as np

from jlm.banks import Bank, targets

SEED = 0
RANK_CAP = 32767
NAMED_IN_PROMPT = {"directed_modulation"}  # the instruction names the concept: no leak exclusion  # jle's rank for a cell with no accepted vocabulary id
N_BOOT = 10_000


def normalise(piece: str) -> str:
    return (piece.removeprefix(" ")).casefold()


Extra = Mapping[str, Iterable[str]]


def form_key(forms: Iterable[str]) -> str:
    return "|".join(sorted(forms))


def accepted_forms(item: dict[str, Any], extra: Extra | None = None) -> frozenset[str]:
    base = frozenset(normalise(t) for t in targets(item) if t)
    return base | frozenset(extra.get(form_key(base), ())) if extra else base


def accepted_ids(vocab_display: list[str], bank: Bank, extra: Extra | None = None) -> dict[str, list[int]]:
    """Per item, the vocabulary ids whose display string normalises to an accepted form."""
    by_form: dict[str, list[int]] = defaultdict(list)
    for i, t in enumerate(vocab_display):
        by_form[normalise(t)].append(i)
    return {it["id"]: sorted({i for f in accepted_forms(it, extra) for i in by_form.get(f, [])}) for it in bank.items}


def confirmatory(bank: Bank, accepted: dict[str, list[int]], prompt_tokens: dict[str, list[str]],
                 extra: Extra | None = None) -> dict[str, str]:
    """Item id -> "" if scored, else the reason it is excluded. With ``extra``, a prompt token spelling any added
    form is a leak too; reachability stays the bench's (its own target is a single word)."""
    out = {}
    for it in bank.items:
        own = accepted_forms(it)
        forms = accepted_forms(it, extra)
        if not any(f and " " not in f for f in own):
            out[it["id"]] = "unreachable"
        elif bank.family not in NAMED_IN_PROMPT and any(normalise(t) in forms for t in prompt_tokens[it["id"]]):
            out[it["id"]] = "leak"
        elif bank.family == "basic_readout" and it.get("subfamily") == "implicit":
            out[it["id"]] = "implicit"
        else:
            out[it["id"]] = ""
    return out


def strict_items(rows: Iterable[dict[str, Any]], bank: Bank, extra: Extra | None = None) -> dict[str, bool]:
    """Item id -> passes (any cell at any layer has an accepted top-10 token)."""
    forms = {it["id"]: accepted_forms(it, extra) for it in bank.items}
    hit: dict[str, bool] = {it["id"]: False for it in bank.items}
    for r in rows:
        if not hit[r["id"]] and any(normalise(t) in forms[r["id"]] for t in r["tokens"]):
            hit[r["id"]] = True
    return hit


def best_rank(ranks: Iterable[dict[str, Any]]) -> dict[str, int]:
    """Item id -> best (lowest) target rank over its cells and layers; ``RANK_CAP`` when no
    vocabulary token spells a target."""
    out: dict[str, int] = {}
    for r in ranks:
        k = r["rank"] if r["rank"] >= 0 else RANK_CAP
        out[r["id"]] = min(out.get(r["id"], k), k)
    return out


def rate(passes: dict[str, bool], ids: list[str]) -> dict[str, Any]:
    """Pass rate over ``ids`` with a seeded item-bootstrap 95 % interval."""
    x = np.array([passes[i] for i in ids], dtype=float)
    if not len(x):
        return {"n": 0, "value": None, "ci95": None}
    rng = np.random.default_rng(SEED)
    boot = x[rng.integers(0, len(x), (N_BOOT, len(x)))].mean(1)
    return {"n": len(x), "value": float(x.mean()), "ci95": [float(np.quantile(boot, 0.025)), float(np.quantile(boot, 0.975))]}


def paired(a: dict[str, bool], b: dict[str, bool], ids: list[str]) -> dict[str, Any]:
    """Rate(a) - rate(b) over ``ids``, paired item bootstrap 95 % interval."""
    d = np.array([float(a[i]) - float(b[i]) for i in ids])
    if not len(d):
        return {"n": 0, "diff": None, "ci95": None}
    rng = np.random.default_rng(SEED)
    boot = d[rng.integers(0, len(d), (N_BOOT, len(d)))].mean(1)
    return {"n": len(d), "diff": float(d.mean()), "ci95": [float(np.quantile(boot, 0.025)), float(np.quantile(boot, 0.975))]}

"""The 27B J-lens without the model: ``W_U``, the final norm gain and the transports ``J_l``.

Three maps: ``jlens`` (the released n1000 wikitext lens, the bench's; every centre is read through it), ``jpp``
(the J++ lens, Ayonrinde & Lindsey 2026) and ``logit`` (the logit lens: no map, ``J_l = I``, the state read straight
through the final norm and ``W_U``). The last two are comparison maps, never a centre's lens. Each is one linear
``J_l`` per layer, so the readouts and centring apply to any of them unchanged. A study can add a map it fitted itself
as ``out/maps/<name>.pt`` (:data:`MAPS`): it reads as ``<name>:`` like the others.

Two readouts, both linear in the state, so a centred read is ``L(h) - L(mu)``:
``cos`` (the bench's): ``(W_U J h)_t / ||J^T W_U[t]||``;
``rms`` (jle's): ``rms_norm(J h, 1 + w) W_U^T``.
"""

import hashlib
import json
from functools import cache
from pathlib import Path

import torch
from huggingface_hub import hf_hub_download
from safetensors import safe_open
from umot.provenance import PINS

from jlm import OUT, REPO_ROOT

MODEL = "Qwen/Qwen3.6-27B"
LENS_REPO = "neuronpedia/jacobian-lens"
LENS_FILE = "qwen3.6-27b/jlens/Salesforce-wikitext/Qwen3.6-27B_jacobian_lens_n1000.pt"
#: map name -> (HF repo, file); revisions from ``PINS``.
LENSES = {"jlens": (LENS_REPO, LENS_FILE), "jpp": ("koayon/jpp-lenses", "qwen3.6-27b/lens.pt"),
          "logit": (MODEL, "logit-lens (no map: final norm + lm_head)")}
#: Maps with no file: J_l is the identity (pinned by the model's own revision).
IDENTITY = {"logit"}
#: Locally fitted maps: ``<name>.pt`` holding ``{"J": {layer: [d, d]}}``, registered as ``(None, path)`` and pinned by
#: content hash. They live under ``out/`` and reach the other machine through the shared dataset (``maps`` scope).
MAPS = OUT / "maps"


def local_maps(root: Path = MAPS) -> dict[str, tuple[None, str]]:
    return {p.stem: (None, str(p)) for p in sorted(root.glob("*.pt"))}


LENSES |= {k: v for k, v in local_maps().items() if k not in LENSES}
READOUTS = ("cos", "rms")
RMS_EPS = 1e-6  # config.json rms_norm_eps
DENOM_CACHE = OUT / "lens"


@cache
def _digest(path: str, mtime: float) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while chunk := f.read(1 << 24):
            h.update(chunk)
    return h.hexdigest()[:16]


def reader(name: str) -> tuple[str, str]:
    """(the map, its revision) for provenance: an HF file at its pin, or a local map's path and content hash."""
    repo, file = LENSES[name]
    if repo is None:
        p = Path(file)
        return str(p.relative_to(REPO_ROOT) if p.is_relative_to(REPO_ROOT) else p), "sha256:" + _digest(file, p.stat().st_mtime)
    return f"{repo}/{file}", PINS[repo]


def load_maps(name: str, layers: list[int], device: str = "cpu") -> dict[int, torch.Tensor]:
    """``J_l`` of map ``name`` at ``layers``, fp32 on ``device`` (none for an identity map)."""
    if name in IDENTITY:
        return {}
    repo, file = LENSES[name]
    path = file if repo is None else hf_hub_download(repo, file, revision=PINS[repo])
    obj = torch.load(path, map_location="cpu", weights_only=False, mmap=True)
    obj = obj.get("parameters", obj)  # J++ nests its maps under "parameters"
    jac = obj["J"] if "J" in obj else obj["jacobians"]
    get = (lambda L: jac[L] if L in jac else jac[str(L)]) if isinstance(jac, dict) else jac.__getitem__
    return {L: get(L).float().clone().to(device) for L in layers}


def _model_tensor(suffix: str) -> torch.Tensor:
    rev = PINS[MODEL]
    index = json.loads(Path(hf_hub_download(MODEL, "model.safetensors.index.json", revision=rev)).read_text())
    key = next(k for k in index["weight_map"] if k == suffix or k.endswith("." + suffix))
    with safe_open(hf_hub_download(MODEL, index["weight_map"][key], revision=rev), framework="pt") as f:
        return f.get_tensor(key)


class Lens:
    """The pinned lens ``name`` (a ``LENSES`` key) at ``layers``, fp32 on ``device``."""

    def __init__(self, layers: list[int], device: str = "cpu", name: str = "jlens", share: "Lens | None" = None) -> None:
        """``share``: another map's lens whose tokenizer, ``W_U`` and norm gain this one reuses (same model)."""
        from transformers import AutoTokenizer

        self.layers, self.device, self.name = sorted(layers), device, name
        self.repo, self.file = LENSES[name]
        if share is not None:
            self.tokenizer, self.w_u, self.gain = share.tokenizer, share.w_u, share.gain
        else:
            self.tokenizer = AutoTokenizer.from_pretrained(MODEL, revision=PINS[MODEL])
            self.w_u = _model_tensor("lm_head.weight").float().to(device)  # [V, d]
            self.gain = (1 + _model_tensor("language_model.norm.weight").float()).to(device)
        self.identity = name in IDENTITY
        self.jac = load_maps(name, self.layers, device)  # the logit lens: none
        self.denom = {L: self._denominator(L) for L in self.layers}

    @property
    def vocab(self) -> int:
        return self.w_u.shape[0]

    def _denominator(self, layer: int, chunk: int = 16384) -> torch.Tensor:
        """``||J_l^T W_U[t]||`` per token (the bench's, clamped at 1e-9), cached on disk."""
        key = self.name if self.identity else PINS[self.repo][:8] if self.repo else f"{self.name}-{reader(self.name)[1][7:15]}"
        path = DENOM_CACHE / f"cos-denom-{key}-L{layer:03d}.pt"
        if path.exists():
            return torch.load(path).to(self.device)
        d = torch.cat(
            [(self.w_u[i : i + chunk] if self.identity else self.w_u[i : i + chunk] @ self.jac[layer]).norm(dim=1)
             for i in range(0, self.vocab, chunk)]
        ).clamp_min(1e-9)
        path.parent.mkdir(parents=True, exist_ok=True)
        torch.save(d.cpu(), path)
        return d

    def scores(self, x: torch.Tensor, layer: int, readout: str) -> torch.Tensor:
        """[n, V] readout scores of states ``x`` [n, d] (already centred by the caller)."""
        z = x.to(self.device, torch.float32)
        if not self.identity:
            z = z @ self.jac[layer].T
        if readout == "cos":
            return (z @ self.w_u.T) / self.denom[layer]
        if readout == "rms":
            z = self.gain * z / torch.sqrt(z.square().mean(dim=1, keepdim=True) + RMS_EPS)
            return z @ self.w_u.T
        raise ValueError(f"readout {readout!r} not in {READOUTS}")

    def logits(self, h: torch.Tensor) -> torch.Tensor:
        """[n, V] the model's own next-token logits from final-block states ``h`` (``context.FINAL_LAYER``)."""
        z = h.to(self.device, torch.float32)
        z = self.gain * z / torch.sqrt(z.square().mean(dim=1, keepdim=True) + RMS_EPS)
        return z @ self.w_u.T

    def display(self, ids: list[int]) -> list[str]:
        from wsbench.produce.render import display_tokens

        return display_tokens(self.tokenizer, ids)

"""Centres ``g`` for the readout ``J_l (h - g)`` ("mu" when g is a mean).

A centre is fitted on a reference set of captures and then gives ``g`` for a read cell. The simple form is
``__call__(CellRef) -> mu``; a centre whose g depends on the state itself, on other layers or on earlier
positions implements ``transform(Batch) -> h - g`` instead (``apply`` picks). It sees
a ``CellRef``: the item id, family, layer, read position and token and the rendered prompt up to
the read cell, but never the item's targets. That is the "no crystal ball" rule, enforced by
what the pipeline passes, not by convention. An item never contributes to its own centre, nor
does any item of its group (DM: the pair's twin, which holds the same concept, as umot's
concept-aware exclusion). So fitting on the read set itself gives leave-one-group-out means
(jle's loo1) and fitting on a dev bank gives held-out means (jle's dev1).
"""

from collections import defaultdict
from collections.abc import Hashable
from dataclasses import dataclass
from typing import TYPE_CHECKING, Protocol

import torch
from umot.capture import ItemCapture

if TYPE_CHECKING:
    from jlm.context import ContextStore


@dataclass(frozen=True)
class CellRef:
    item: str
    group: str  # items of one group never centre each other (the item id unless the bank pairs items)
    family: str
    layer: int
    i: int  # index into the item's read cells
    pos: int  # read position as the plan reports it
    token: str  # the read-site token
    context: tuple[str, ...]  # decoded render up to and including the read token


def cell_refs(items: list[ItemCapture], family: str, layer: int, groups: dict[str, str] | None = None) -> list[CellRef]:
    groups = groups or {}
    return [
        CellRef(it.id, groups.get(it.id, it.id), family, layer, i, it.positions[i], it.token(i),
                tuple(it.decoded[: it.idx[i] + 1]))
        for it in items
        for i in range(len(it.positions))
    ]


@dataclass
class Batch:
    """What a centre may look at to read one layer of a bank: the read cells, their states, the bank's
    read-cell captures (every captured layer) and, when a context capture exists and the centre asks for it
    (``needs_ctx``), every position's state. Never the targets."""

    layer: int
    cells: list[CellRef]
    H: torch.Tensor  # [n, d] float32, the states at ``cells``
    items: dict[str, ItemCapture]
    ctx: "ContextStore | None" = None


class Centre(Protocol):
    name: str
    doc: str
    needs_ctx: bool  # optional (default False): fit and transform want every-position states

    def fit(self, ref: list[ItemCapture], family: str, groups: dict[str, str] | None = None,
            ctx: "ContextStore | None" = None) -> None: ...

    def __call__(self, cell: CellRef) -> torch.Tensor: ...  # [d] float32; or instead:
    # def transform(self, batch: Batch) -> torch.Tensor: ...  # [n, d] float32, the states to read (h - g)

    def support(self, cell: CellRef) -> tuple[int, bool]: ...  # (reference cells behind mu, fell back)

    # Optional, for the dashboard's per-cell view of how mu is chosen (centres that average reference cells):
    # def reference(self, layer: int) -> tuple[torch.Tensor, list[tuple[str, str, str]]]: ...  # pool [N, d], (group, family, token)
    # def members(self, batch: Batch) -> list[torch.Tensor]: ...  # per cell, the reference rows averaged into its mu


def apply(centre: "Centre", batch: Batch) -> torch.Tensor:
    """The states the lens reads, ``h - g`` [n, d] float32: the centre's own ``transform`` if it has one,
    else ``g = centre(cell)`` per cell."""
    if hasattr(centre, "transform"):
        return centre.transform(batch)
    return batch.H - torch.stack([centre(c) for c in batch.cells])


class Zero:
    """``mu = 0``: the released lens's uncentred readout."""

    name, doc = "zero", "no centring (the released lens reads J h)"

    def fit(self, ref: list[ItemCapture], family: str, groups: dict[str, str] | None = None, ctx=None) -> None:
        self.d = next(iter(ref[0].acts.values())).shape[1]

    def __call__(self, cell: CellRef) -> torch.Tensor:
        return torch.zeros(self.d)

    def support(self, cell: CellRef) -> tuple[int, bool]:
        return 0, False


class KeyedMean:
    """Mean over reference cells sharing ``key(cell)``, excluding the cell's own item. Below
    ``min_cells`` remaining cells it uses ``fallback``. Sums are float64."""

    def __init__(self, name: str, doc: str, *, min_cells: int = 1, fallback: "Centre | None" = None) -> None:
        self.name, self.doc, self.min_cells, self.fallback = name, doc, min_cells, fallback
        self.n_fallback = 0

    def key(self, cell: CellRef) -> Hashable:
        raise NotImplementedError

    def fit(self, ref: list[ItemCapture], family: str, groups: dict[str, str] | None = None, ctx=None) -> None:
        self._ref, self._family, self._groups = ref, family, groups  # for reference() / members()
        self.s: dict = defaultdict(float)  # (layer, key) -> sum
        self.n: dict = defaultdict(int)
        self.own: dict = defaultdict(lambda: [0.0, 0])  # (layer, key, group) -> [sum, n]
        for layer in sorted({L for it in ref for L in it.acts}):
            for it in ref:
                if layer not in it.acts:
                    continue
                acts = it.acts[layer]
                for c in cell_refs([it], family, layer, groups):
                    k, h = (layer, self.key(c)), acts[c.i].double()
                    self.s[k] = self.s[k] + h
                    self.n[k] += 1
                    o = self.own[(*k, c.group)]
                    o[0], o[1] = o[0] + h, o[1] + 1
        if self.fallback is not None:
            self.fallback.fit(ref, family, groups)
        self.n_fallback = 0
        self._memo: dict = {}

    def __call__(self, cell: CellRef) -> torch.Tensor:
        k = (cell.layer, self.key(cell))
        if (*k, cell.group) in self._memo:  # same key and group -> same mean
            hit, mu = self._memo[(*k, cell.group)]
            self.n_fallback += hit
            return mu
        mu = self._mean(cell, k)
        self._memo[(*k, cell.group)] = (self._last_fallback, mu)
        return mu

    def _mean(self, cell: CellRef, k: tuple) -> torch.Tensor:
        self._last_fallback = 0
        s, n = self.s.get(k, 0.0), self.n.get(k, 0)
        if (*k, cell.group) in self.own:
            o = self.own[(*k, cell.group)]
            s, n = s - o[0], n - o[1]
        if n < self.min_cells:
            if self.fallback is None:
                raise ValueError(f"{cell.item} L{cell.layer}: {n} reference cells for key {k[1]!r}")
            self.n_fallback += 1
            self._last_fallback = 1
            return self.fallback(cell)
        return (s / n).float()

    def support(self, cell: CellRef) -> tuple[int, bool]:
        """(reference cells averaged into this cell's mu, whether it fell back), as ``__call__`` decides."""
        k = (cell.layer, self.key(cell))
        n = self.n.get(k, 0) - self.own.get((*k, cell.group), (0.0, 0))[1]
        if n < self.min_cells and self.fallback is not None:
            return self.fallback.support(cell)[0], True
        return n, False

    def _rows(self, layer: int) -> list[CellRef]:
        return cell_refs([it for it in self._ref if layer in it.acts], self._family, layer, self._groups)

    def reference(self, layer: int) -> tuple[torch.Tensor, list[tuple[str, str, str]]]:
        rows, by_id = self._rows(layer), {it.id: it for it in self._ref}
        return (torch.stack([by_id[c.item].acts[layer][c.i].float() for c in rows]),
                [(c.group, c.family, c.token) for c in rows])

    def members(self, batch: Batch) -> list[torch.Tensor]:
        """Per cell, the reference rows (in ``reference`` order) averaged into its mu, as ``__call__`` decides."""
        rows, out = self._rows(batch.layer), []
        for cell in batch.cells:
            n, fell = self.support(cell)
            if fell:
                out.append(self.fallback.members(Batch(batch.layer, [cell], batch.H[:1], batch.items))[0])
                continue
            k = self.key(cell)
            out.append(torch.tensor([j for j, c in enumerate(rows) if self.key(c) == k and c.group != cell.group], dtype=torch.long))
        return out


class FamilyMean(KeyedMean):
    """One mean per layer over every reference cell of the family (jle's loo1 / dev1)."""

    def __init__(self) -> None:
        super().__init__("fam", "mean over every reference cell at the layer, own item and its group excluded")

    def key(self, cell: CellRef) -> Hashable:
        return cell.family


class TokenMean(KeyedMean):
    """Mean over reference cells with the same read token (jle's tok1), else the family mean."""

    def __init__(self, min_cells: int = 3) -> None:
        super().__init__(
            "tok",
            f"mean over reference cells with the same read token (>= {min_cells} cells, else fam)",
            min_cells=min_cells,
            fallback=FamilyMean(),
        )

    def key(self, cell: CellRef) -> Hashable:
        return (cell.family, cell.token)


def _derangement(n: int, seed: int) -> torch.Tensor:
    """A random permutation of ``range(n)`` with no fixed point (one random cycle), for n >= 2."""
    p = torch.randperm(n, generator=torch.Generator().manual_seed(seed))
    out = torch.empty(n, dtype=torch.long)
    out[p] = p.roll(-1)
    return out


class Shuffled:
    """Control: every cell is read with the g of another read cell at the same layer (a seeded random cycle
    over the bank's cells), the arm otherwise unchanged. If this matches the arm, the gain does not come from
    matching g to the cell. Identical to the arm when g is one vector per layer (``fam``)."""

    def __init__(self, inner: Centre, seed: int = 0) -> None:
        self.inner, self.seed = inner, seed
        self.name, self.doc = f"shuf.{inner.name}", f"control: another cell's g ({inner.doc})"
        self.needs_ctx = getattr(inner, "needs_ctx", False)

    def fit(self, ref, family, groups=None, ctx=None) -> None:
        self.inner.fit(ref, family, groups, ctx)

    def transform(self, batch: Batch) -> torch.Tensor:
        G = batch.H - apply(self.inner, batch)
        if len(G) < 2:
            return batch.H - G
        return batch.H - G[_derangement(len(G), self.seed * 1000 + batch.layer)]

    def support(self, cell: CellRef) -> tuple[int, bool]:
        return self.inner.support(cell)


class RandomDir:
    """Control: g replaced by a random direction (one per layer, seeded) with each cell's ||g||. If this
    matches the arm, the gain is a norm or bias effect, not content."""

    def __init__(self, inner: Centre, seed: int = 0) -> None:
        self.inner, self.seed = inner, seed
        self.name, self.doc = f"rand.{inner.name}", f"control: a random direction with ||g|| of ({inner.doc})"
        self.needs_ctx = getattr(inner, "needs_ctx", False)

    def fit(self, ref, family, groups=None, ctx=None) -> None:
        self.inner.fit(ref, family, groups, ctx)

    def transform(self, batch: Batch) -> torch.Tensor:
        norms = (batch.H - apply(self.inner, batch)).norm(dim=1, keepdim=True)
        u = torch.randn(batch.H.shape[1], generator=torch.Generator().manual_seed(self.seed * 1000 + batch.layer))
        return batch.H - norms * (u / u.norm())

    def support(self, cell: CellRef) -> tuple[int, bool]:
        return self.inner.support(cell)


CENTRES: dict[str, type] = {"zero": Zero, "fam": FamilyMean, "tok": TokenMean}
#: Control wrappers: ``shuf.<centre>``, ``rand.<centre>`` (see notes/iteration-anthony/research-loop.md, "Controls").
CONTROLS = {"shuf": Shuffled, "rand": RandomDir}
#: Parametric names ``<head>:<args>`` (``genk:8``, ``dict:fam:0.5``): a study module registers a factory taking
#: ``<args>``; ``make`` uses it only when the full name is not a ``CENTRES`` key.
PARAMETRIC: dict = {}


def make(name: str) -> Centre:
    """A centre by arm name: a ``CENTRES`` key, a study centre (``jlm.mu``), or a control prefix on either."""
    head, dot, rest = name.partition(".")
    if dot and head in CONTROLS:
        return CONTROLS[head](make(rest))
    if name not in CENTRES:
        import jlm.mu  # noqa: F401  (study modules register their centres on import)
    head, colon, rest = name.partition(":")
    if name not in CENTRES and colon and head in PARAMETRIC:
        return PARAMETRIC[head](rest)
    return CENTRES[name]()

"""Item banks in the bench's ``items.json`` format: the frozen bench, and our dev banks.

A bank is ``(family, split)``. ``bench`` is WorkspaceBench's own file, read in place and never
copied. ``fit`` (fit and select centres) and ``val`` (confirm, LLM-judged) are dev banks under
``data/dev/<family>/<split>.json``, written in the same format so the bench's plan and judges
take them unchanged.
"""

from collections.abc import Iterator
from contextlib import contextmanager
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from wsbench import readplan
from wsbench.banks import exact_targets, item_targets, load_bank
from wsbench.registry import REPO_ROOT as WSBENCH_ROOT

from jlm import REPO_ROOT

DEV_ROOT = REPO_ROOT / "data" / "dev"
SPLITS = ("fit", "val", "bench")
#: Held-out dev splits read by name only (``typo/val2``), never iterated with SPLITS: they exist for a few families
#: (S24's val2: fresh items, no target shared with the bench, fit, val or each other), so loops over SPLITS skip them.
HELD_OUT = ("val2", "val2b", "val3")


@dataclass(frozen=True)
class Bank:
    family: str
    split: str
    path: Path
    header: dict[str, Any]
    items: list[dict[str, Any]]  # each with ``id`` (the readout id), as wsbench.banks.load_bank sets

    @property
    def name(self) -> str:
        return f"{self.family}/{self.split}"

    def by_id(self) -> dict[str, dict[str, Any]]:
        return {it["id"]: it for it in self.items}


def path_of(family: str, split: str) -> Path:
    if split == "bench":
        return WSBENCH_ROOT / "evals" / family / "items.json"
    if split not in SPLITS + HELD_OUT:
        raise ValueError(f"split {split!r} not in {SPLITS + HELD_OUT}")
    return DEV_ROOT / family / f"{split}.json"


def load(family: str, split: str) -> Bank:
    path = path_of(family, split)
    header, items = load_bank(path)
    return Bank(family, split, path, header, items)


#: Dev families imported from elsewhere, read on their own only: kept out of the pooled references and the screens that
#: iterate every dev family (poetry: the J++ paper's items, half of them WorkspaceBench bench prompts; see
#: experiments/import_jpp_poetry.py). chain / brew intermediates: fresh categories for J++ and our centres alike
#: (experiments/build_intermediates_dev.py), kept out so pooled refs and screens stay as the studies fitted them.
NOT_POOLED = ("poetry", "chain_intermediates", "brew_intermediates")


def dev_families() -> list[str]:
    """The dev families with a ``fit`` bank, those in :data:`NOT_POOLED` left out."""
    return sorted(p.parent.name for p in DEV_ROOT.glob("*/fit.json") if p.parent.name not in NOT_POOLED)


def targets(item: dict[str, Any]) -> list[str]:
    """The bench's target strings for a single-token item (the bank judge's rule)."""
    return exact_targets(item_targets(item))


def specs(bank: Bank) -> list[readplan.ReadSpec]:
    """The bench's read plan (render, positions rule, layers) applied to this bank's items."""
    if bank.split == "bench":
        return readplan.plan(bank.family)
    with _plan_reads(bank):
        out = readplan.plan(bank.family)
    if [s.id for s in out] != [it["id"] for it in bank.items]:
        raise RuntimeError(f"{bank.name}: the bench's planner for this family does not read _bank")
    return out


@contextmanager
def _plan_reads(bank: Bank) -> Iterator[None]:
    """Point ``readplan``'s bank loader at ``bank`` while planning (the bench is never edited)."""
    orig = readplan._bank

    def _bank(family: str) -> tuple[dict[str, Any], list[dict[str, Any]]]:
        return (bank.header, bank.items) if family == bank.family else orig(family)

    readplan._bank = _bank
    try:
        yield
    finally:
        readplan._bank = orig

